package wordcount

import (
	"reflect"
	"testing"
)

func TestWordCount(t *testing.T) {
	counts := WordCount("hello world hello")
	if counts["hello"] != 2 || counts["world"] != 1 {
		t.Errorf("unexpected counts: %v", counts)
	}
}

func TestWordCountCaseInsensitive(t *testing.T) {
	counts := WordCount("Go go GO")
	if counts["go"] != 3 {
		t.Errorf("expected go=3, got %v", counts)
	}
}

func TestWordCountPunctuation(t *testing.T) {
	counts := WordCount("hello, world!")
	if _, ok := counts["hello,"]; ok {
		t.Error("punctuation should be stripped")
	}
	if counts["hello"] != 1 || counts["world"] != 1 {
		t.Errorf("unexpected counts: %v", counts)
	}
}

func TestTopN(t *testing.T) {
	counts := map[string]int{"apple": 5, "banana": 3, "cherry": 5, "date": 1}
	top := TopN(counts, 2)
	// apple and cherry both have 5; tie broken alphabetically
	if !reflect.DeepEqual(top, []string{"apple", "cherry"}) {
		t.Errorf("TopN got %v, want [apple cherry]", top)
	}
}
